/** Generated at build time from /public/images (see vite.config.ts). */
declare module "virtual:site-assets" {
  /** Public path of the logo, or null if none has been added. */
  export const logo: string | null;
  /** Filenames in /public/images/products */
  export const productImages: string[];
  /** Filenames in /public/images/flyers */
  export const flyerImages: string[];
  /** Filenames in /public/images/gallery */
  export const galleryImages: string[];
}
